"""Static Pix (BR Code) charges, generated by the Node service (qrcode-pix + qrcode) and locked to the order total."""

import logging

from lib.ai import wa_call

logger = logging.getLogger(__name__)


async def gerar_pix(valor: float, id_pedido: str, settings: dict) -> dict | None:
    """Returns {"copiaECola", "qrCodeBase64", "valor", "txid"} or None when Pix BR Code is unavailable."""
    if not settings.get("pix_key") or round(valor or 0, 2) <= 0:
        return None
    res = await wa_call("POST", "/pix", {
        "chave": settings["pix_key"],
        "tipoChave": settings.get("pix_key_type", ""),
        "nome": settings.get("pix_beneficiary") or settings.get("store_name", ""),
        "cidade": settings.get("pix_city", ""),
        "valor": round(valor, 2),
        "idPedido": id_pedido,
    })
    if not res.get("copiaECola"):
        logger.warning("pix brcode indisponível: %s", res.get("detail"))
        return None
    return res
